class BankAccount:
    def __init__(self, initial_balance=0):
        self.balance = initial_balance

    def deposit(self, amount):
        self.balance += amount

    def withdraw(self, amount):
        if amount <= self.balance:
            self.balance -= amount
            return True
        return False

acc = BankAccount(100)
acc.deposit(50)
print(acc.withdraw(30))
print('Balance:', acc.balance)

