class LibraryBook:
    def __init__(self, title):
        self.title = title
        self.available = True

    def borrow(self):
        if self.available:
            self.available = False
            return 'Borrowed successfully'
        return 'Book already borrowed'

    def return_book(self):
        self.available = True
        return 'Book returned'

b1 = LibraryBook('Python Basics')
print(b1.borrow())
print(b1.borrow())
print(b1.return_book())
